import React, { useState, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, LineChart, Line, 
  PieChart, Pie, Cell, ResponsiveContainer, AreaChart, Area, RadialBarChart, RadialBar 
} from 'recharts';
import { 
  Activity, AlertTriangle, DollarSign, Clock, CheckCircle, XCircle, 
  RefreshCcw, Settings, TrendingUp, TrendingDown, Users, FileText,
  Eye, Filter, Download, Calendar, Building, CreditCard, Search,
  ArrowUpDown, ChevronLeft, ChevronRight, Target, BarChart3,
  PieChart as PieChartIcon, Zap, Shield, Award, Heart
} from 'lucide-react';

interface ComprehensiveKPIs {
  // Core Financial Metrics
  total_claims: number;
  denied_claims: number;
  paid_claims: number;
  pending_claims: number;
  total_charges: number;
  total_payments: number;
  total_adjustments: number;
  net_collection_rate: number;
  gross_collection_rate: number;
  
  // Denial Management KPIs
  denial_rate: number;
  clean_claim_rate: number;
  first_pass_resolution_rate: number;
  resubmission_count: number;
  appeals_pending: number;
  appeal_success_rate: number;
  denial_overturn_rate: number;
  
  // Accounts Receivable KPIs
  days_in_ar: number;
  aging_0_30_days: number;
  aging_31_60_days: number;
  aging_61_90_days: number;
  aging_over_90_days: number;
  ar_over_90_percentage: number;
  ar_over_120_percentage: number;
  
  // Operational KPIs
  cost_to_collect: number;
  charges_lag_days: number;
  coding_accuracy_rate: number;
  prior_auth_approval_rate: number;
  patient_pay_yield: number;
  bad_debt_percentage: number;
  
  // Productivity KPIs
  claims_processed_per_fte: number;
  revenue_per_fte: number;
  registration_accuracy_rate: number;
  insurance_verification_rate: number;
  
  // Patient Experience KPIs
  patient_satisfaction_score: number;
  patient_payment_plan_adoption: number;
  patient_portal_adoption: number;
  average_patient_balance: number;
}

interface DashboardProps {
  data: ComprehensiveKPIs;
}

const ComprehensiveKPIDashboard: React.FC<DashboardProps> = ({ data }) => {
  const [activeSection, setActiveSection] = useState('overview');

  // Render Enhanced KPI Card with 3D effects
  const renderEnhancedKPICard = (
    title: string, 
    value: string, 
    change: string, 
    trend: 'up' | 'down' | 'neutral', 
    icon: React.ReactNode, 
    gradient: string,
    target?: string,
    benchmark?: string
  ) => (
    <div className={`enhanced-kpi-card ${gradient}`}>
      <div className="kpi-card-inner">
        <div className="kpi-header">
          <div className="kpi-icon-container">
            {icon}
          </div>
          <div className={`kpi-trend trend-${trend}`}>
            {trend === 'up' ? <TrendingUp size={16} /> : trend === 'down' ? <TrendingDown size={16} /> : <Target size={16} />}
            <span>{change}</span>
          </div>
        </div>
        
        <div className="kpi-body">
          <div className="kpi-value-section">
            <h3 className="kpi-value">{value}</h3>
            <p className="kpi-title">{title}</p>
          </div>
          
          {(target || benchmark) && (
            <div className="kpi-benchmarks">
              {target && <div className="benchmark-item target">Target: {target}</div>}
              {benchmark && <div className="benchmark-item benchmark">Benchmark: {benchmark}</div>}
            </div>
          )}
        </div>
        
        <div className="kpi-progress-bar">
          <div className={`progress-fill ${trend}`}></div>
        </div>
      </div>
      
      <div className="kpi-glow-effect"></div>
    </div>
  );

  // Render KPI Section
  const renderKPISection = (title: string, children: React.ReactNode, icon: React.ReactNode) => (
    <div className="kpi-section-container">
      <div className="section-header">
        <div className="section-title">
          {icon}
          <h3>{title}</h3>
        </div>
      </div>
      <div className="section-content">
        {children}
      </div>
    </div>
  );

  // AR Aging Visualization
  const agingData = [
    { name: '0-30 Days', value: data.aging_0_30_days, color: '#10b981' },
    { name: '31-60 Days', value: data.aging_31_60_days, color: '#f59e0b' },
    { name: '61-90 Days', value: data.aging_61_90_days, color: '#ef4444' },
    { name: '90+ Days', value: data.aging_over_90_days, color: '#7c3aed' }
  ];

  // Denial Categories Data
  const denialTrendData = [
    { month: 'Jan', denials: 45, appeals: 12, overturned: 8 },
    { month: 'Feb', denials: 38, appeals: 15, overturned: 11 },
    { month: 'Mar', denials: 42, appeals: 18, overturned: 12 },
    { month: 'Apr', denials: 35, appeals: 14, overturned: 10 },
    { month: 'May', denials: 29, appeals: 11, overturned: 7 },
    { month: 'Jun', denials: 32, appeals: 13, overturned: 9 }
  ];

  return (
    <div className="comprehensive-kpi-dashboard">
      {/* Navigation Tabs */}
      <div className="dashboard-navigation">
        <div className="nav-tabs-container">
          {[
            { id: 'overview', label: 'Overview', icon: <BarChart3 size={18} /> },
            { id: 'financial', label: 'Financial', icon: <DollarSign size={18} /> },
            { id: 'denials', label: 'Denials', icon: <AlertTriangle size={18} /> },
            { id: 'operations', label: 'Operations', icon: <Settings size={18} /> },
            { id: 'productivity', label: 'Productivity', icon: <Zap size={18} /> },
            { id: 'patient', label: 'Patient Experience', icon: <Heart size={18} /> }
          ].map(tab => (
            <button
              key={tab.id}
              className={`nav-tab ${activeSection === tab.id ? 'active' : ''}`}
              onClick={() => setActiveSection(tab.id)}
            >
              {tab.icon}
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Dashboard Content */}
      <div className="dashboard-content">
        {activeSection === 'overview' && (
          <>
            {/* Critical KPIs - Most Important Metrics */}
            {renderKPISection('Critical Performance Indicators', (
              <div className="critical-kpis-grid">
                {renderEnhancedKPICard(
                  'Net Collection Rate',
                  `${data.net_collection_rate}%`,
                  '+2.3%',
                  'up',
                  <DollarSign size={24} />,
                  'blue-gradient',
                  '98%',
                  '95-99%'
                )}
                {renderEnhancedKPICard(
                  'Days in A/R',
                  `${data.days_in_ar} days`,
                  '-4.5%',
                  'down',
                  <Clock size={24} />,
                  'green-gradient',
                  '<25 days',
                  '20-35 days'
                )}
                {renderEnhancedKPICard(
                  'Denial Rate',
                  `${data.denial_rate}%`,
                  '-1.8%',
                  'down',
                  <AlertTriangle size={24} />,
                  'red-gradient',
                  '<5%',
                  '<5%'
                )}
                {renderEnhancedKPICard(
                  'Clean Claim Rate',
                  `${data.clean_claim_rate}%`,
                  '+3.2%',
                  'up',
                  <CheckCircle size={24} />,
                  'purple-gradient',
                  '>95%',
                  '>95%'
                )}
              </div>
            ), <Target size={20} />)}

            {/* Overview Charts */}
            <div className="overview-charts-grid">
              {/* AR Aging Pie Chart */}
              <div className="chart-container">
                <div className="chart-header">
                  <h4>A/R Aging Distribution</h4>
                  <div className="chart-subtitle">Current aging breakdown</div>
                </div>
                <ResponsiveContainer width="100%" height={300}>
                  <PieChart>
                    <Pie
                      data={agingData}
                      cx="50%"
                      cy="50%"
                      outerRadius={100}
                      dataKey="value"
                      label={({name, value}) => `${name}: ${value}%`}
                    >
                      {agingData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
              </div>

              {/* Collection Performance */}
              <div className="chart-container">
                <div className="chart-header">
                  <h4>Collection Performance</h4>
                  <div className="chart-subtitle">Monthly collection trends</div>
                </div>
                <ResponsiveContainer width="100%" height={300}>
                  <LineChart data={denialTrendData}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="month" />
                    <YAxis />
                    <Tooltip />
                    <Line type="monotone" dataKey="denials" stroke="#ef4444" strokeWidth={2} name="Denials" />
                    <Line type="monotone" dataKey="appeals" stroke="#3b82f6" strokeWidth={2} name="Appeals" />
                    <Line type="monotone" dataKey="overturned" stroke="#10b981" strokeWidth={2} name="Overturned" />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </div>
          </>
        )}

        {activeSection === 'financial' && (
          <>
            {renderKPISection('Financial Performance Metrics', (
              <div className="financial-kpis-grid">
                {renderEnhancedKPICard(
                  'Total Charges',
                  `$${(data.total_charges / 1000).toFixed(0)}K`,
                  '+12.4%',
                  'up',
                  <Activity size={24} />,
                  'blue-gradient'
                )}
                {renderEnhancedKPICard(
                  'Total Payments',
                  `$${(data.total_payments / 1000).toFixed(0)}K`,
                  '+8.7%',
                  'up',
                  <DollarSign size={24} />,
                  'green-gradient'
                )}
                {renderEnhancedKPICard(
                  'Gross Collection Rate',
                  `${data.gross_collection_rate}%`,
                  '+1.2%',
                  'up',
                  <TrendingUp size={24} />,
                  'teal-gradient'
                )}
                {renderEnhancedKPICard(
                  'Bad Debt %',
                  `${data.bad_debt_percentage}%`,
                  '-0.5%',
                  'down',
                  <Shield size={24} />,
                  'red-gradient',
                  '<2%',
                  '<3%'
                )}
              </div>
            ), <DollarSign size={20} />)}

            {/* A/R Aging Detailed View */}
            {renderKPISection('Accounts Receivable Aging Analysis', (
              <div className="ar-aging-detailed">
                <div className="aging-summary">
                  <div className="aging-item">
                    <div className="aging-label">0-30 Days</div>
                    <div className="aging-value good">{data.aging_0_30_days}%</div>
                    <div className="aging-bar">
                      <div className="aging-fill good" style={{width: `${data.aging_0_30_days}%`}}></div>
                    </div>
                  </div>
                  <div className="aging-item">
                    <div className="aging-label">31-60 Days</div>
                    <div className="aging-value warning">{data.aging_31_60_days}%</div>
                    <div className="aging-bar">
                      <div className="aging-fill warning" style={{width: `${data.aging_31_60_days}%`}}></div>
                    </div>
                  </div>
                  <div className="aging-item">
                    <div className="aging-label">61-90 Days</div>
                    <div className="aging-value danger">{data.aging_61_90_days}%</div>
                    <div className="aging-bar">
                      <div className="aging-fill danger" style={{width: `${data.aging_61_90_days}%`}}></div>
                    </div>
                  </div>
                  <div className="aging-item">
                    <div className="aging-label">90+ Days</div>
                    <div className="aging-value critical">{data.aging_over_90_days}%</div>
                    <div className="aging-bar">
                      <div className="aging-fill critical" style={{width: `${data.aging_over_90_days}%`}}></div>
                    </div>
                  </div>
                </div>
              </div>
            ), <Clock size={20} />)}
          </>
        )}

        {activeSection === 'denials' && (
          <>
            {renderKPISection('Denial Management KPIs', (
              <div className="denial-kpis-grid">
                {renderEnhancedKPICard(
                  'First Pass Resolution',
                  `${data.first_pass_resolution_rate}%`,
                  '+5.1%',
                  'up',
                  <CheckCircle size={24} />,
                  'green-gradient',
                  '>90%',
                  '>85%'
                )}
                {renderEnhancedKPICard(
                  'Appeal Success Rate',
                  `${data.appeal_success_rate}%`,
                  '+3.8%',
                  'up',
                  <TrendingUp size={24} />,
                  'blue-gradient',
                  '>80%',
                  '>70%'
                )}
                {renderEnhancedKPICard(
                  'Denial Overturn Rate',
                  `${data.denial_overturn_rate}%`,
                  '+2.1%',
                  'up',
                  <RefreshCcw size={24} />,
                  'purple-gradient'
                )}
                {renderEnhancedKPICard(
                  'Appeals Pending',
                  `${data.appeals_pending}`,
                  '-15%',
                  'down',
                  <AlertTriangle size={24} />,
                  'yellow-gradient'
                )}
              </div>
            ), <AlertTriangle size={20} />)}
          </>
        )}

        {activeSection === 'operations' && (
          <>
            {renderKPISection('Operational Excellence', (
              <div className="operational-kpis-grid">
                {renderEnhancedKPICard(
                  'Cost to Collect',
                  `${data.cost_to_collect}%`,
                  '-0.8%',
                  'down',
                  <Activity size={24} />,
                  'green-gradient',
                  '<3%',
                  '2-4%'
                )}
                {renderEnhancedKPICard(
                  'Coding Accuracy',
                  `${data.coding_accuracy_rate}%`,
                  '+1.2%',
                  'up',
                  <FileText size={24} />,
                  'blue-gradient',
                  '>98%',
                  '>95%'
                )}
                {renderEnhancedKPICard(
                  'Prior Auth Approval',
                  `${data.prior_auth_approval_rate}%`,
                  '+2.4%',
                  'up',
                  <Shield size={24} />,
                  'purple-gradient',
                  '>95%',
                  '>90%'
                )}
                {renderEnhancedKPICard(
                  'Charge Lag Days',
                  `${data.charges_lag_days} days`,
                  '-0.3%',
                  'down',
                  <Clock size={24} />,
                  'teal-gradient',
                  '<2 days',
                  '<3 days'
                )}
              </div>
            ), <Settings size={20} />)}
          </>
        )}

        {activeSection === 'productivity' && (
          <>
            {renderKPISection('Productivity Metrics', (
              <div className="productivity-kpis-grid">
                {renderEnhancedKPICard(
                  'Claims per FTE',
                  `${data.claims_processed_per_fte}`,
                  '+8.5%',
                  'up',
                  <Users size={24} />,
                  'blue-gradient'
                )}
                {renderEnhancedKPICard(
                  'Revenue per FTE',
                  `$${(data.revenue_per_fte / 1000).toFixed(0)}K`,
                  '+12.3%',
                  'up',
                  <DollarSign size={24} />,
                  'green-gradient'
                )}
                {renderEnhancedKPICard(
                  'Registration Accuracy',
                  `${data.registration_accuracy_rate}%`,
                  '+0.8%',
                  'up',
                  <CheckCircle size={24} />,
                  'purple-gradient',
                  '>99%',
                  '>98%'
                )}
                {renderEnhancedKPICard(
                  'Insurance Verification',
                  `${data.insurance_verification_rate}%`,
                  '+1.5%',
                  'up',
                  <CreditCard size={24} />,
                  'teal-gradient',
                  '>95%',
                  '>95%'
                )}
              </div>
            ), <Zap size={20} />)}
          </>
        )}

        {activeSection === 'patient' && (
          <>
            {renderKPISection('Patient Experience Metrics', (
              <div className="patient-kpis-grid">
                {renderEnhancedKPICard(
                  'Patient Satisfaction',
                  `${data.patient_satisfaction_score}/5`,
                  '+0.2',
                  'up',
                  <Heart size={24} />,
                  'pink-gradient',
                  '4.5+',
                  '4.0+'
                )}
                {renderEnhancedKPICard(
                  'Portal Adoption',
                  `${data.patient_portal_adoption}%`,
                  '+5.3%',
                  'up',
                  <Users size={24} />,
                  'blue-gradient',
                  '>80%',
                  '>70%'
                )}
                {renderEnhancedKPICard(
                  'Payment Plan Adoption',
                  `${data.patient_payment_plan_adoption}%`,
                  '+3.1%',
                  'up',
                  <CreditCard size={24} />,
                  'green-gradient'
                )}
                {renderEnhancedKPICard(
                  'Avg Patient Balance',
                  `$${data.average_patient_balance}`,
                  '-$12',
                  'down',
                  <DollarSign size={24} />,
                  'teal-gradient'
                )}
              </div>
            ), <Heart size={20} />)}
          </>
        )}
      </div>
    </div>
  );
};

export default ComprehensiveKPIDashboard;